import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]);
        }

        List<Integer> subSums = new ArrayList<>();
        int bestResult = 0;

        int firstHalfSize = (n / 2) + (n % 2);
        int secondHalfSize = n - firstHalfSize;

        int limitFirst = 1 << firstHalfSize;
        int limitSecond = 1 << secondHalfSize;

        // Generate all subset sums for the first half
        for (int subsetMask = 0; subsetMask < limitFirst; subsetMask++) {
            int sumPart = 0;
            int currentMask = subsetMask;
            for (int i = 0; i < firstHalfSize; i++) {
                if ((currentMask & 1) == 1) {
                    sumPart += a[i];
                }
                currentMask >>= 1;
            }
            subSums.add(sumPart % m);
        }

        Collections.sort(subSums);

        // For each subset in the second half, find the best complement
        for (int secondMask = 0; secondMask < limitSecond; secondMask++) {
            int sumSecond = 0;
            int maskCopy = secondMask;
            for (int j = 0; j < secondHalfSize; j++) {
                if ((maskCopy & 1) == 1) {
                    sumSecond += a[firstHalfSize + j];
                }
                maskCopy >>= 1;
            }
            sumSecond %= m;

            int target = m - sumSecond - 1;
            int idx = Collections.binarySearch(subSums, target);
            if (idx < 0) {
                idx = -idx - 1;
            }

            int candidate;
            if (idx < subSums.size()) {
                candidate = subSums.get(idx);
                if (candidate > target && idx - 1 >= 0) {
                    candidate = subSums.get(idx - 1);
                }
            } else {
                candidate = subSums.get(subSums.size() - 1);
            }

            int candidateSum1 = (sumSecond + candidate) % m;
            int candidateSum2 = (sumSecond + subSums.get(subSums.size() - 1)) % m;
            bestResult = Math.max(bestResult, Math.max(candidateSum1, candidateSum2));
        }

        System.out.println(bestResult);
    }
}
